input.content:
#include <map>
#include <string>
#include <tuple>
#include <vector>
#include <fmt/ranges.h>

int main() {
  std::vector<std::vector<char>> vvc{{'a', 'b', 'c'}, {'a', 'b', 'c'}};
  fmt::print("A: {}\n", fmt::format("{}", vvc));
  fmt::print("B: {}\n", fmt::format("{:n}", vvc));
  fmt::print("C: {}\n", fmt::format("{:n:n}", vvc));
  fmt::print("D: {}\n", fmt::format("{:n:n:}", vvc));
  std::vector<char> vc{'a', 'b'};
  fmt::print("E: {} {:n}\n", vc, vc);
  std::vector<int> vi{1, 2};
  fmt::print("F: {} {:n}\n", vi, vi);
  fmt::print("G: {}\n", fmt::format("{}", std::map<std::string, int>{{"one", 1}}));
  fmt::print("H: {}\n", fmt::format("{}", std::tuple<char, char>{'x', 'y'}));
  fmt::print("I: {}\n", fmt::format("{}", std::vector<std::string>{"one", "two"}));
  fmt::print("J: {}\n", fmt::format("{}", std::vector<std::vector<int>>{{1, 2}, {3}}));
}

#include <ranges>
#include <string>
#include <fmt/ranges.h>

struct X {
  template <std::ranges::range R>
  X(R&& r) : sv(&*std::ranges::begin(r), std::ranges::distance(r)) {}
  auto begin() { return sv.begin(); }
  auto end() { return sv.end(); }
  std::string_view sv;
};

int main() {
  std::string line = "abc";
  X x(line);
  fmt::print("top-level X: {}\n", x);
  const auto& cx = x;
  fmt::print("const X: {}\n", cx);
}

